```javascript
const axios = require("axios");

async function signUpAndSendOtp(userData) {
  try {
    const signUpResponse = await axios.post(
      "https://customer.flip.id/web/user-auth/api/v3.1/sign-up",
      {
        name: userData.name,
        email: userData.email,
        phone_number: userData.phone_number,
        credential: userData.credential,
        referral_code: userData.referral_code || "",
        platform: userData.platform,
        device_model: userData.device_model,
        version: userData.version,
        os_version: userData.os_version,
        device_identifier: userData.device_identifier,
        source: userData.source,
      },
      {
        headers: {
          "Content-Type": "application/json",
          "x-internal-api-key": "VlhObGNsQnliMlpwYkdWQmJtUkJkWFJvWlc1MGFXTmhkR2x2YmxObGNuWnBZMlU2T1RBNQ==",
          "Accept-Language": "id-ID",
          "Content-Language": "id-ID",
          "Accept": "application/json, text/plain, */*",
        },
      }
    );

    if (signUpResponse.data && signUpResponse.data.code === 2002 && signUpResponse.data.data && signUpResponse.data.data.token) {
      const token = signUpResponse.data.data.token;

      const otpResponse = await axios.post(
        "https://customer.flip.id/web/user-auth/api/v3.1/otp",
        {
          credential: userData.credential,
          channel: "via-wa-by-service",
          type: 12,
          device_identifier: userData.device_identifier,
          phone_number: userData.phone_number,
        },
        {
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${token}`,
            "x-internal-api-key": "VlhObGNsQnliMlpwYkdWQmJtUkJkWFJvWlc1MGFXTmhkR2x2YmxObGNuWnBZMlU2T1RBNQ==",
            "Accept-Language": "id-ID",
            "Content-Language": "id-ID",
            "Accept": "application/json, text/plain, */*",
          },
        }
      );
      return { signUp: signUpResponse.data, otp: otpResponse.data };
    } else {
      return { signUp: signUpResponse.data, otp: { error: "Gagal mendapatkan token dari sign up" } };
    }
  } catch (error) {
    if (error.response) {
      return { error: `Request failed with status ${error.response.status}: ${JSON.stringify(error.response.data)}` };
    } else if (error.request) {
      return { error: "No response received from server" };
    } else {
      return { error: error.message };
    }
  }
}

const userData = {
  name: "roshan",
  email: "qog3r6gpt3@olipii.com",
  phone_number: "+628319193958",
  credential: "+628319193958",
  referral_code: "",
  platform: "web",
  device_model: "X665E mobile Infinix",
  version: "1036",
  os_version: "12",
  device_identifier: "9542a760-6dc1-4650-9aa8-8a5f0e7fc761",
  source: "gogogo",
};

signUpAndSendOtp(userData)
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
